from .test_import_data import TEST_SCHEMA, CornillonMajic, import_options, remove_schema

# The copropriete, the parcel with the largest building
COPROPRIETE = "1320290000A0107"


def fetch(sql: str) -> list:
    # Do not keep the connection object, it is invalidated when connections are reloaded
    metadata = QgsProviderRegistry.instance().providerMetadata("postgres")
    return metadata.findConnection("test_database").executeSql(sql)


@pytest.fixture(scope="module")
def database(fixtures: Path) -> CadastreDatabase:
    remove_schema()
    metadata = QgsProviderRegistry.instance().providerMetadata("postgres")
    metadata.findConnection("test_database").createSchema(TEST_SCHEMA)
    assert cadastreImport(import_options(CornillonMajic, fixtures), CadastreFeedback()).run()
    return CadastreDatabase.from_connection("postgis", "test_database", TEST_SCHEMA)


@pytest.fixture(scope="module")
def parcelles(database: CadastreDatabase) -> Iterator[QgsVectorLayer]:
    """ The parcelle_info layer, used by the fiche parcellaire and the export """
    project = QgsProject.instance()
    project.clear()
    CadastreLoading(CadastreFeedback()).process_loading(LoadingOptions(database, main_layers_only=True))
    yield project.mapLayersByName("Parcelles")[0]
    project.clear()


def feature(layer: QgsVectorLayer, geo_parcelle: str) -> QgsFeature:
    request = QgsFeatureRequest().setFilterExpression(f"\"geo_parcelle\" = '{geo_parcelle}'")
    return next(layer.getFeatures(request))


@pytest.mark.parametrize(
    "table, count",
    [
        ("parcelle", 389),
        ("geo_parcelle", 389),
        ("parcelle_info", 389),
        ("comptecommunal", 72),
        ("local10", 166),
        ("pev", 166),
        ("pdl", 1),
        ("lots", 5),
        ("lotslocaux", 5),
    ],
)
def test_counts(database: CadastreDatabase, table: str, count: int):
    assert fetch(f"SELECT count(*) FROM cadastre.{table}") == [[count]]


@pytest.mark.parametrize(
    "sql",
    [
        # EDIGEO <-> MAJIC
        "SELECT count(*) FROM cadastre.parcelle p "
        "LEFT JOIN cadastre.geo_parcelle g ON g.geo_parcelle = p.parcelle WHERE g.geo_parcelle IS NULL",
        "SELECT count(*) FROM cadastre.geo_parcelle g "
        "LEFT JOIN cadastre.parcelle p ON g.geo_parcelle = p.parcelle WHERE p.parcelle IS NULL",
        # Parcels and owners
        "SELECT count(*) FROM cadastre.parcelle p "
        "LEFT JOIN cadastre.proprietaire pr ON pr.comptecommunal = p.comptecommunal WHERE pr.proprietaire IS NULL",
        "SELECT count(*) FROM cadastre.suf s "
        "LEFT JOIN cadastre.parcelle p ON p.parcelle = s.parcelle WHERE p.parcelle IS NULL",
        # Buildings
        "SELECT count(*) FROM cadastre.local10 l "
        "LEFT JOIN cadastre.parcelle p ON p.parcelle = l.parcelle WHERE p.parcelle IS NULL",
        "SELECT count(*) FROM cadastre.local10 l "
        "LEFT JOIN cadastre.comptecommunal c ON c.comptecommunal = l.comptecommunal WHERE c.comptecommunal IS NULL",
        "SELECT count(*) FROM cadastre.local10 l "
        "LEFT JOIN cadastre.pev p ON p.local10 = l.local10 WHERE p.pev IS NULL",
        "SELECT count(*) FROM cadastre.pev p "
        "LEFT JOIN cadastre.pevtaxation t ON t.pev = p.pev WHERE t.pev IS NULL",
        # Copropriete
        "SELECT count(*) FROM cadastre.lotslocaux ll "
        "LEFT JOIN cadastre.local10 l ON l.local10 = ll.local10 WHERE l.local10 IS NULL",
        "SELECT count(*) FROM cadastre.lots l "
        "LEFT JOIN cadastre.comptecommunal c ON c.comptecommunal = l.comptecommunal WHERE c.comptecommunal IS NULL",
        # Addresses and TOPO
        "SELECT count(*) FROM cadastre.parcelle p LEFT JOIN cadastre.voie v "
        "ON SUBSTR(p.voie, 1, 6) || SUBSTR(p.voie, 12, 4) = SUBSTR(v.voie, 1, 6) || SUBSTR(v.voie, 12, 4) "
        "WHERE v.voie IS NULL",
    ],
    ids=[
        "parcelle-geo_parcelle", "geo_parcelle-parcelle", "parcelle-proprietaire", "suf-parcelle",
        "local-parcelle", "local-compte", "local-pev", "pev-taxation", "lot-local", "lot-compte", "parcelle-voie",
    ],
)
def test_links(database: CadastreDatabase, sql: str):
    """ Every row has its related row """
    assert fetch(sql) == [[0]]


def test_lots(database: CadastreDatabase):
    """ Numerator and denominator of the lots, on 7 characters """
    assert fetch("SELECT DISTINCT dnumql, ddenql FROM cadastre.lots ORDER BY 1") == [[400, 10000], [2400, 10000]]


def test_exonerations(database: CadastreDatabase):
    assert fetch("SELECT count(*) > 0 FROM cadastre.sufexoneration") == [[True]]
    assert fetch("SELECT count(*) > 0 FROM cadastre.pevexoneration") == [[True]]


def test_parcelle_info(database: CadastreDatabase):
    rows = fetch(f"SELECT adresse, proprietaire FROM cadastre.parcelle_info WHERE geo_parcelle = '{COPROPRIETE}'")
    adresse, proprietaire = rows[0]
    assert "CHEM DE LA COOPERATIVE" in adresse
    assert "COPROPRIETE LE CLOS DES OLIVIERS - Propriétaire" in proprietaire
    assert "PROVENCE GESTION IMMOBILIERE - Syndic de copropriété" in proprietaire


@pytest.mark.parametrize(
    "item, expected",
    [
        ("parcelle_majic", "CORNILLON-CONFOUX"),
        ("proprietaires", "COPROPRIETE LE CLOS DES OLIVIERS"),
        ("indivisions", "Détails"),
        ("subdivisions", "Subdivisions fiscales"),
        ("locaux", "Appartement"),
        ("locaux_detail", "Habitation"),
    ],
)
def test_fiche_parcellaire(parcelles: QgsVectorLayer, item: str, expected: str):
    """ Tabs of the fiche parcellaire, for the copropriete """
    params = common_utils.getConnectionParameterFromDbLayer(parcelles)
    connector = common_utils.getConnectorFromUri(params)

    html = common_utils.getItemHtml(item, feature(parcelles, COPROPRIETE), params, connector)

    assert expected in html


@pytest.mark.parametrize("etype", ["proprietaire", "parcelle"])
def test_releve_pdf(parcelles: QgsVectorLayer, tmp_path: Path, etype: str):
    """ Relevé de propriété of the owner of a house """
    geo_parcelle, compte = fetch(
        "SELECT p.parcelle, p.comptecommunal FROM cadastre.parcelle p "
        "JOIN cadastre.local10 l ON l.parcelle = p.parcelle "
        "WHERE p.comptecommunal NOT LIKE '%+%' ORDER BY p.parcelle LIMIT 1"
    )[0]

    export = CadastreExport(QgsProject.instance(), parcelles, etype, compte, geo_parcelle, str(tmp_path))
    paths = export.export_as_pdf()

    assert len(paths) == 1
    assert Path(paths[0]).stat().st_size > 10000

    # Only native layout items, no HTML item which needs QtWebKit
    layout = export.currentComposition
    assert layout is not None
    multi_frames = layout.multiFrames()
    assert multi_frames
    assert all(isinstance(item, QgsLayoutItemManualTable) for item in multi_frames)


def test_releve_zones(parcelles: QgsVectorLayer):
    """ The main tables, with the lines of a page, fit in their zone, otherwise lines would not be drawn """
    export = CadastreExport(QgsProject.instance(), parcelles, "proprietaire", "132029+00005", COPROPRIETE)
    export.set_composer_templates("132029+00005")

    # Title, groups of columns, titles of the columns, lines, and the grid strokes
    needed = 4 + 3.5 + releve_layout.HEADER_HEIGHT + export.maxLineNumber * ROW_HEIGHT + 3 * releve_layout.GRID_STROKE
    for key in ("proprietes_baties", "proprietes_non_baties"):
        assert needed <= export.composerTemplates[key]["position"][3], key


@pytest.mark.parametrize("lines, pages", [(0, 1), (1, 1), (15, 1), (16, 2), (30, 2), (31, 3)])
def test_releve_pages(parcelles: QgsVectorLayer, lines: int, pages: int, monkeypatch: pytest.MonkeyPatch):
    """ Number of pages, depending on the number of lines of the longest table """
    export = CadastreExport(QgsProject.instance(), parcelles, "proprietaire", "132029+00005", COPROPRIETE)
    export.set_composer_templates("132029+00005")
    monkeypatch.setattr(export, "getDataForGivenItem", lambda key, item, page=None: [])
    export.lineCount["proprietes_baties_line"]["count"] = lines
    export.lineCount["proprietes_non_baties_line"]["count"] = 2

    export.getPageNumberNeeded()

    assert export.numPages == pages
